style:
.tms-mlm{
  --tms-green:#198754;--tms-green-d:#0f5132;--tms-bg:#ffffff;--tms-fg:#1f2d3d;
  --tms-muted:#6c757d;--tms-line:#e5e7eb;--tms-shadow:0 8px 24px rgba(0,0,0,.06);
  background:var(--tms-bg);border:1px solid var(--tms-line);border-radius:14px;
  overflow:hidden;color:var(--tms-fg);font-family:inherit;box-shadow:var(--tms-shadow);
}
.tms-mlm-header{display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:12px 16px;background:linear-gradient(180deg,#0f5132,#198754);color:#fff;
  flex-wrap:wrap;}
.tms-mlm-title{display:flex;align-items:center;gap:10px;font-weight:600;font-size:15px;}
.tms-mlm-title-text{letter-spacing:.2px;}
.tms-mlm-dot{width:10px;height:10px;border-radius:50%;background:#34d399;
  box-shadow:0 0 0 0 rgba(52,211,153,.7);animation:tms-pulse 1.6s infinite;}
@keyframes tms-pulse{0%{box-shadow:0 0 0 0 rgba(52,211,153,.6);}
  70%{box-shadow:0 0 0 10px rgba(52,211,153,0);}100%{box-shadow:0 0 0 0 rgba(52,211,153,0);}}
.tms-mlm-live-pill{background:rgba(255,255,255,.18);padding:2px 8px;border-radius:999px;
  font-size:11px;font-weight:700;letter-spacing:.6px;}
.tms-mlm-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.tms-mlm-updated{font-size:12px;color:rgba(255,255,255,.8);}
.tms-mlm-btn{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);
  color:#fff;padding:6px 12px;border-radius:8px;font-size:13px;cursor:pointer;
  transition:background .15s ease;}
.tms-mlm-btn:hover{background:rgba(255,255,255,.25);}
.tms-mlm-btn-primary{background:#fff;color:var(--tms-green-d);border-color:#fff;font-weight:600;}
.tms-mlm-btn-primary:hover{background:#f1f5f9;}

.tms-mlm-body{display:grid;grid-template-columns:1fr 320px;gap:0;}
.tms-mlm-map-wrap{position:relative;background:#eef2f6;}
.tms-mlm-map{width:100%;height:60vh;min-height:360px;}
.tms-mlm-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.7);pointer-events:none;transition:opacity .25s;}
.tms-mlm-overlay.tms-hidden{opacity:0;visibility:hidden;}
.tms-mlm-overlay-msg{padding:8px 14px;background:#fff;border-radius:8px;
  box-shadow:0 4px 12px rgba(0,0,0,.08);font-size:13px;color:var(--tms-muted);}

.tms-mlm-side{border-left:1px solid var(--tms-line);display:flex;flex-direction:column;
  max-height:calc(60vh + 0px);min-height:360px;background:#fafbfc;}
.tms-mlm-side-head{display:flex;align-items:center;justify-content:space-between;
  padding:12px 14px;border-bottom:1px solid var(--tms-line);background:#fff;}
.tms-mlm-side-title{font-weight:600;font-size:13px;letter-spacing:.4px;
  text-transform:uppercase;color:var(--tms-muted);}
.tms-mlm-side-count{background:var(--tms-green);color:#fff;border-radius:999px;
  padding:1px 9px;font-size:12px;font-weight:700;}
.tms-mlm-side-list{overflow-y:auto;padding:8px;display:flex;flex-direction:column;gap:6px;flex:1;}
.tms-mlm-empty{color:var(--tms-muted);font-size:13px;padding:24px 12px;text-align:center;}

.tms-mlm-card{border:1px solid var(--tms-line);border-radius:10px;padding:10px 12px;
  background:#fff;cursor:pointer;transition:border-color .15s,box-shadow .15s;}
.tms-mlm-card:hover{border-color:var(--tms-green);box-shadow:0 4px 10px rgba(25,135,84,.08);}
.tms-mlm-card.tms-active{border-color:var(--tms-green);box-shadow:0 4px 10px rgba(25,135,84,.15);}
.tms-mlm-card-top{display:flex;align-items:center;justify-content:space-between;gap:8px;
  margin-bottom:6px;}
.tms-mlm-card-vehicle{font-weight:700;font-size:13px;color:var(--tms-fg);}
.tms-mlm-card-pill{font-size:10px;font-weight:700;padding:2px 8px;border-radius:999px;
  text-transform:uppercase;letter-spacing:.4px;}
.tms-mlm-card-pill.fresh{background:#d1fae5;color:#065f46;}
.tms-mlm-card-pill.stale{background:#fee2e2;color:#991b1b;}
.tms-mlm-card-row{font-size:12px;color:var(--tms-muted);display:flex;
  align-items:center;justify-content:space-between;gap:6px;}
.tms-mlm-card-row b{color:var(--tms-fg);font-weight:600;}

@media (max-width:880px){
  .tms-mlm-body{grid-template-columns:1fr;}
  .tms-mlm-map{height:50vh;min-height:320px;}
  .tms-mlm-side{border-left:0;border-top:1px solid var(--tms-line);max-height:none;}
  .tms-mlm-side-list{max-height:40vh;}
}
@media (max-width:480px){
  .tms-mlm-header{padding:10px 12px;}
  .tms-mlm-meta{width:100%;justify-content:flex-end;}
  .tms-mlm-updated{flex:1;}
  .tms-mlm-map{height:48vh;min-height:300px;}
}

script:
// Manager Live Map — runs once per block instance. Frappe passes `root`
// (the block's container DOM element) into this function scope.
(function(){
  var rootEl = (typeof root !== 'undefined' && root)
    ? root
    : document.querySelector('.tms-mlm');
  if (!rootEl || rootEl._tmsInit) return;
  rootEl._tmsInit = true;

  var $ = function(sel){ return rootEl.querySelector('[data-tms="'+sel+'"]'); };
  var mapEl  = $('map');
  var listEl = $('list');
  var emptyEl= $('empty');
  var countEl= $('count');
  var updEl  = $('updated');
  var ovrEl  = $('overlay');
  var fitBtn = $('fit');
  var refBtn = $('refresh');

  var state = { map:null, markers:{}, selected:null, lastFetch:null, timer:null };

  function setOverlay(text, hide){
    if (text) ovrEl.querySelector('.tms-mlm-overlay-msg').textContent = text;
    ovrEl.classList.toggle('tms-hidden', !!hide);
  }
  function fmtAgo(min){
    if (min == null) return '—';
    if (min < 1) return 'just now';
    if (min < 60) return Math.round(min)+' min ago';
    var h = Math.floor(min/60), m = Math.round(min%60);
    return h+'h '+(m?m+'m ':'')+'ago';
  }
  function setUpdated(){
    var t = new Date(); var hh = String(t.getHours()).padStart(2,'0');
    var mm = String(t.getMinutes()).padStart(2,'0');
    var ss = String(t.getSeconds()).padStart(2,'0');
    updEl.textContent = 'Updated ' + hh+':'+mm+':'+ss;
  }

  function ensureLeaflet(cb){
    if (window.L) return cb();
    var css = document.getElementById('tms-leaflet-css');
    if (!css){
      css = document.createElement('link');
      css.id = 'tms-leaflet-css'; css.rel = 'stylesheet';
      css.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
      document.head.appendChild(css);
    }
    var s = document.createElement('script');
    s.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    s.onload = cb;
    s.onerror = function(){ setOverlay('Failed to load map library.', false); };
    document.head.appendChild(s);
  }

  function initMap(){
    state.map = L.map(mapEl, { zoomControl:true })
      .setView([13.0827, 80.2707], 11); // Chennai default
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
      { maxZoom:19, attribution:'© OpenStreetMap' }).addTo(state.map);
    setTimeout(function(){ state.map.invalidateSize(); }, 200);
    window.addEventListener('resize', function(){
      if (state.map) state.map.invalidateSize();
    });
  }

  function markerIcon(stale){
    var color = stale ? '#dc2626' : '#198754';
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="34" height="44" viewBox="0 0 34 44">'+
              '<path fill="'+color+'" stroke="#fff" stroke-width="2" d="M17 2C9 2 3 8 3 16c0 11 14 26 14 26s14-15 14-26C31 8 25 2 17 2z"/>'+
              '<circle cx="17" cy="16" r="6" fill="#fff"/></svg>';
    return L.divIcon({
      className: 'tms-mlm-mk',
      html: svg,
      iconSize:[34,44], iconAnchor:[17,42], popupAnchor:[0,-36],
    });
  }

  function upsertMarker(loc){
    if (!state.map || loc.latitude == null || loc.longitude == null) return;
    var key = loc.vehicle;
    var ll = [loc.latitude, loc.longitude];
    var m = state.markers[key];
    if (!m){
      m = L.marker(ll, { icon: markerIcon(loc.is_stale) }).addTo(state.map);
      m.bindPopup(popupHtml(loc));
      m.on('click', function(){ selectVehicle(key); });
      state.markers[key] = m;
    } else {
      m.setLatLng(ll);
      m.setIcon(markerIcon(loc.is_stale));
      m.setPopupContent(popupHtml(loc));
    }
  }
  function popupHtml(loc){
    return '<div style="font-size:13px;line-height:1.5;">'+
      '<b>'+loc.vehicle+'</b><br>'+
      'Speed: '+(loc.speed_kmph!=null?loc.speed_kmph+' km/h':'—')+'<br>'+
      'Last seen: '+fmtAgo(loc.minutes_ago)+
      '</div>';
  }

  function renderList(locs){
    countEl.textContent = locs.length;
    emptyEl.style.display = locs.length ? 'none' : 'block';
    // Remove old cards (keep the empty-state element)
    Array.prototype.slice.call(listEl.querySelectorAll('.tms-mlm-card')).forEach(function(n){ n.remove(); });
    locs.forEach(function(loc){
      var card = document.createElement('div');
      card.className = 'tms-mlm-card' + (state.selected === loc.vehicle ? ' tms-active' : '');
      card.setAttribute('data-vehicle', loc.vehicle);
      card.innerHTML =
        '<div class="tms-mlm-card-top">'+
          '<span class="tms-mlm-card-vehicle">'+loc.vehicle+'</span>'+
          '<span class="tms-mlm-card-pill '+(loc.is_stale?'stale':'fresh')+'">'+
            (loc.is_stale?'STALE':'LIVE')+'</span>'+
        '</div>'+
        '<div class="tms-mlm-card-row"><span>Speed</span><b>'+
          (loc.speed_kmph!=null?loc.speed_kmph+' km/h':'—')+'</b></div>'+
        '<div class="tms-mlm-card-row"><span>Last seen</span><b>'+fmtAgo(loc.minutes_ago)+'</b></div>';
      card.addEventListener('click', function(){ selectVehicle(loc.vehicle); });
      listEl.appendChild(card);
    });
  }

  function selectVehicle(vehicle){
    state.selected = vehicle;
    Array.prototype.slice.call(listEl.querySelectorAll('.tms-mlm-card')).forEach(function(n){
      n.classList.toggle('tms-active', n.getAttribute('data-vehicle') === vehicle);
    });
    var m = state.markers[vehicle];
    if (m){ state.map.setView(m.getLatLng(), Math.max(state.map.getZoom(), 14)); m.openPopup(); }
  }

  function fitAll(){
    var pts = Object.values(state.markers).map(function(m){ return m.getLatLng(); });
    if (!pts.length) return;
    state.map.fitBounds(L.latLngBounds(pts).pad(0.2));
  }

  function refresh(){
    setOverlay('Loading…', false);
    return frappe.call({
      method: 'transport_management.transport_management.api.gps.get_live_vehicle_locations',
      args: { stale_minutes: 10 },
    }).then(function(r){
      var locs = (r && r.message) || [];
      locs.forEach(upsertMarker);
      // Remove markers whose vehicle is no longer in the live set.
      var live = {}; locs.forEach(function(l){ live[l.vehicle]=1; });
      Object.keys(state.markers).forEach(function(k){
        if (!live[k]){ state.map.removeLayer(state.markers[k]); delete state.markers[k]; }
      });
      renderList(locs);
      setUpdated();
      state.lastFetch = Date.now();
      setOverlay('', true);
      if (locs.length && !state._fittedOnce){ fitAll(); state._fittedOnce = true; }
    }, function(){ setOverlay('Failed to load locations.', false); });
  }

  function subscribeRealtime(){
    if (!window.frappe || !frappe.realtime) return;
    try { frappe.realtime.doctype_subscribe('Vehicle GPS Log'); } catch(e){}
    frappe.realtime.on('tms_vehicle_location', function(msg){
      if (!msg) return;
      // Compute minutes_ago locally so the card reflects "just now".
      msg.minutes_ago = 0; msg.is_stale = false;
      upsertMarker(msg);
      // Refresh the sidebar with the latest computed list (re-pull every few seconds
      // would be wasteful; do an optimistic local upsert instead).
      mergeLocalUpdate(msg);
      setUpdated();
    });
    frappe.realtime.on('tms_geofence_event', function(msg){
      if (!msg || !msg.label) return;
      frappe.show_alert({ message: msg.label, indicator: 'green' }, 6);
    });
  }

  function mergeLocalUpdate(loc){
    // Update the sidebar card in place if present; otherwise re-fetch.
    var card = listEl.querySelector('.tms-mlm-card[data-vehicle="'+CSS.escape(loc.vehicle)+'"]');
    if (!card){ refresh(); return; }
    var rows = card.querySelectorAll('.tms-mlm-card-row b');
    if (rows[0]) rows[0].textContent = (loc.speed_kmph!=null?loc.speed_kmph+' km/h':'—');
    if (rows[1]) rows[1].textContent = 'just now';
    var pill = card.querySelector('.tms-mlm-card-pill');
    if (pill){ pill.className = 'tms-mlm-card-pill fresh'; pill.textContent = 'LIVE'; }
  }

  fitBtn.addEventListener('click', fitAll);
  refBtn.addEventListener('click', refresh);

  ensureLeaflet(function(){
    initMap();
    setOverlay('', true);
    refresh();
    subscribeRealtime();
    // Fallback poll every 30s in case socket drops.
    state.timer = setInterval(refresh, 30000);
  });
})();
